sys_script.script:
(function () {
    var isrc = current.getValue('isrc');

    // If ISRC is provided, validate its format
    if (isrc) {
        var isrcPattern = /^[A-Z]{2}-[A-Z0-9]{3}-\d{2}-\d{5}$/;
        if (!isrcPattern.test(isrc)) {
            gs.addErrorMessage(
                'Invalid ISRC format. Expected: XX-XXX-YY-NNNNN (e.g., IN-ABC-24-00001)'
            );
            current.setAbortAction(true);
        }
        return;
    }

    // --- Auto-generate ISRC ---

    // Step 1: Look up the label's ISRC prefix via Song → Album → Label
    var albumSysId = current.getValue('album');
    if (!albumSysId) {
        gs.addErrorMessage(
            'Cannot auto-generate ISRC: Song must be associated with an album that has a label.'
        );
        current.setAbortAction(true);
        return;
    }

    var albumGr = new GlideRecord('x_2015479_wa_str_0_album');
    if (!albumGr.get(albumSysId)) {
        gs.addErrorMessage('Cannot auto-generate ISRC: Album not found.');
        current.setAbortAction(true);
        return;
    }

    var labelSysId = albumGr.getValue('label');
    if (!labelSysId) {
        gs.addErrorMessage(
            'Cannot auto-generate ISRC: Album does not have an assigned label.'
        );
        current.setAbortAction(true);
        return;
    }

    var labelGr = new GlideRecord('x_2015479_wa_str_0_label');
    if (!labelGr.get(labelSysId)) {
        gs.addErrorMessage('Cannot auto-generate ISRC: Label not found.');
        current.setAbortAction(true);
        return;
    }

    var prefix = labelGr.getValue('isrc_prefix');
    if (!prefix) {
        gs.addErrorMessage(
            'Cannot auto-generate ISRC: Label does not have an ISRC prefix configured.'
        );
        current.setAbortAction(true);
        return;
    }

    // Step 2: Get current 2-digit year
    var now = new GlideDateTime();
    var dateStr = now.getValue();
    var year = dateStr.substring(2, 4);

    // Step 3: Query for the last assigned sequence number for this prefix + year
    var isrcPrefix = 'IN-' + prefix + '-' + year + '-';
    var songGr = new GlideRecord('x_2015479_wa_str_0_song');
    songGr.addQuery('isrc', 'STARTSWITH', isrcPrefix);
    songGr.orderByDesc('isrc');
    songGr.setLimit(1);
    songGr.query();

    var sequence = 1;
    if (songGr.next()) {
        var lastIsrc = songGr.getValue('isrc');
        var parts = lastIsrc.split('-');
        var lastSeqStr = parts[parts.length - 1];
        var lastSeq = parseInt(lastSeqStr, 10);
        if (!isNaN(lastSeq)) {
            sequence = lastSeq + 1;
        }
    }

    // Step 4: Zero-pad the sequence to 5 digits and assemble the ISRC
    var seqStr = sequence.toString();
    while (seqStr.length < 5) {
        seqStr = '0' + seqStr;
    }
    var generatedIsrc = isrcPrefix + seqStr;

    current.setValue('isrc', generatedIsrc);
    gs.addInfoMessage('Auto-generated ISRC: ' + generatedIsrc);
})();
